INSERT INTO _e VALUES
 ('ENT_PHO_ELIOUN','Elioun (Hypsistos)','deity','deity','Phoenician','the Most High; primordial high god, father of Ouranos and Ge','B','Attested in Philo of Byblos (Eusebius, Praep. Ev. 1.10.15): Elioun called Hypsistos, ''the Most High,'' father of Ouranos (Sky) and Ge (Earth); a primordial generation of the theogony. Name reflects Northwest Semitic ''elyon, ''most high.'''),
 ('ENT_PHO_OURANOS','Ouranos (Phoenician Sky)','deity','deity','Phoenician','the Sky; son of Elioun, brother-consort of Ge, father of Elos/Kronos','B','Phoenician sky-god in Philo of Byblos (Eusebius, Praep. Ev. 1.10.16-21), given the Greek name Ouranos by the author; son of Elioun and consort of his sister Ge, castrated/dethroned by his son Elos (Kronos). Distinct from the Greek Ouranos (ENT_OURANOS) but explicitly equated by Philo.'),
 ('ENT_PHO_GE','Ge (Phoenician Earth)','deity','deity','Phoenician','the Earth; daughter of Elioun, sister-consort of Ouranos','B','Phoenician earth-goddess in Philo of Byblos (Eusebius, Praep. Ev. 1.10.16-21), named Ge (Greek) by the author; sister and consort of Ouranos, mother of Elos/Kronos and his brothers. Phoenician interpretatio of the Greek Gaia (ENT_GAIA).'),
 ('ENT_PHO_ELOS_KRONOS','Elos (Kronos)','deity','deity','Phoenician','the Phoenician El; son of Ouranos and Ge who overthrows his father','B','In Philo of Byblos (Eusebius, Praep. Ev. 1.10.16ff) the chief god Elos is expressly identified with the Greek Kronos (ENT_CRONUS) and corresponds to Northwest Semitic El (ENT_CAN_EL); son of Ouranos and Ge, he castrates and dethrones his father. Represents the Phoenician El within the euhemerized theogony.'),
 ('ENT_PHO_SYDYK','Sydyk','deity','deity','Phoenician','Righteousness; primordial deity, father of the Kabeiroi/Dioskouroi','B','Sydyk (''Righteousness,'' NW Semitic sdq) in Philo of Byblos (Eusebius, Praep. Ev. 1.10.13-14, 1.10.25), paired with Misor; father of the Kabeiroi/Dioskouroi, the discoverers of seafaring.'),
 ('ENT_PHO_MISOR','Misor','deity','deity','Phoenician','Uprightness; primordial deity, father of Taautos','B','Misor (''Uprightness,'' NW Semitic mysr) in Philo of Byblos (Eusebius, Praep. Ev. 1.10.13-14), paired with Sydyk; father of Taautos, the inventor of writing.'),
 ('ENT_PHO_CHOUSOR','Chousor','deity','deity','Phoenician','craftsman-god; discoverer of iron, fishing, magic words and spells','B','Chousor in Philo of Byblos (Eusebius, Praep. Ev. 1.10.11), craftsman and culture-hero who discovered iron-working, the fishhook, the raft, and incantations; the Hellenized form of Ugaritic/Canaanite Kothar-wa-Khasis (ENT_CAN_KOTHAR). Philo also equates him with Hephaistos.'),
 ('ENT_PHO_TAAUTOS','Taautos','deity','deity','Phoenician','scribe-god; inventor of writing and letters','B','Taautos in Philo of Byblos (Eusebius, Praep. Ev. 1.9.24, 1.10.14), the inventor of writing whom the Egyptians call Thoth (ENT_EGY_THOTH) and the Greeks Hermes; son of Misor. Sanchuniathon''s own claimed source. The name renders Egyptian Djehuty (Thoth).'),
 ('ENT_PHO_OUSOOS','Ousoos','human','human','Phoenician','first hunter; culture-hero who first made clothing from skins and sailed','C','Ousoos in Philo of Byblos (Eusebius, Praep. Ev. 1.10.9-10), one of the mortal first generations; a hunter who quarreled with his brother Samemroumos/Hypsouranios, first wore animal skins and dared the sea on a log; later deified. Likely an eponym of Usu, the mainland settlement opposite Tyre.'),
 ('ENT_PHO_SAMEMROUMOS','Samemroumos (Hypsouranios)','human','human','Phoenician','first inhabitant of Tyre; builder of reed-and-papyrus huts','C','Samemroumos, also called Hypsouranios (''High of Heaven''), in Philo of Byblos (Eusebius, Praep. Ev. 1.10.9-10); among the mortal first generations, settler of Tyre and inventor of reed/rush dwellings, brother of Ousoos.'),
 ('ENT_PHO_KABEIROI','The Kabeiroi (Dioskouroi)','collective','collective','Phoenician','sons of Sydyk; discoverers of the raft and seafaring','C','In Philo of Byblos (Eusebius, Praep. Ev. 1.10.25) the seven sons of Sydyk plus Asclepius are the Kabeiroi, called Dioskouroi or Kabeiroi or Corybantes, who first invented the ship/raft; identified with the Great Gods of the Phoenician seafaring cult. A Phoenician interpretatio of the Greek Cabeiri (ENT_CABEIRI)/Dioscuri (ENT_DIOSCURI).');
