INSERT INTO _p VALUES
 ('ENT_PHO_ELIOUN','PER_PHO_IRON_AGE','Attested in Philo of Byblos (Eusebius, Praep. Ev. 1.10.15): Elioun called Hypsistos, ''the Most High,'' father of Ouranos (Sky) and Ge (Earth); a primordial generation of the theogony. Name reflects Northwest Semitic ''elyon, ''most high.'''),
 ('ENT_PHO_OURANOS','PER_PHO_IRON_AGE','Phoenician sky-god in Philo of Byblos (Eusebius, Praep. Ev. 1.10.16-21), given the Greek name Ouranos by the author; son of Elioun and consort of his sister Ge, castrated/dethroned by his son Elos (Kronos). Distinct from the Greek Ouranos (ENT_OURANOS) but explicitly equated by Philo.'),
 ('ENT_PHO_GE','PER_PHO_IRON_AGE','Phoenician earth-goddess in Philo of Byblos (Eusebius, Praep. Ev. 1.10.16-21), named Ge (Greek) by the author; sister and consort of Ouranos, mother of Elos/Kronos and his brothers. Phoenician interpretatio of the Greek Gaia (ENT_GAIA).'),
 ('ENT_PHO_ELOS_KRONOS','PER_PHO_IRON_AGE','In Philo of Byblos (Eusebius, Praep. Ev. 1.10.16ff) the chief god Elos is expressly identified with the Greek Kronos (ENT_CRONUS) and corresponds to Northwest Semitic El (ENT_CAN_EL); son of Ouranos and Ge, he castrates and dethrones his father. Represents the Phoenician El within the euhemerized theogony.'),
 ('ENT_PHO_SYDYK','PER_PHO_IRON_AGE','Sydyk (''Righteousness,'' NW Semitic sdq) in Philo of Byblos (Eusebius, Praep. Ev. 1.10.13-14, 1.10.25), paired with Misor; father of the Kabeiroi/Dioskouroi, the discoverers of seafaring.'),
 ('ENT_PHO_MISOR','PER_PHO_IRON_AGE','Misor (''Uprightness,'' NW Semitic mysr) in Philo of Byblos (Eusebius, Praep. Ev. 1.10.13-14), paired with Sydyk; father of Taautos, the inventor of writing.'),
 ('ENT_PHO_CHOUSOR','PER_PHO_IRON_AGE','Chousor in Philo of Byblos (Eusebius, Praep. Ev. 1.10.11), craftsman and culture-hero who discovered iron-working, the fishhook, the raft, and incantations; the Hellenized form of Ugaritic/Canaanite Kothar-wa-Khasis (ENT_CAN_KOTHAR). Philo also equates him with Hephaistos.'),
 ('ENT_PHO_TAAUTOS','PER_PHO_IRON_AGE','Taautos in Philo of Byblos (Eusebius, Praep. Ev. 1.9.24, 1.10.14), the inventor of writing whom the Egyptians call Thoth (ENT_EGY_THOTH) and the Greeks Hermes; son of Misor. Sanchuniathon''s own claimed source. The name renders Egyptian Djehuty (Thoth).'),
 ('ENT_PHO_OUSOOS','PER_PHO_IRON_AGE','Ousoos in Philo of Byblos (Eusebius, Praep. Ev. 1.10.9-10), one of the mortal first generations; a hunter who quarreled with his brother Samemroumos/Hypsouranios, first wore animal skins and dared the sea on a log; later deified. Likely an eponym of Usu, the mainland settlement opposite Tyre.'),
 ('ENT_PHO_SAMEMROUMOS','PER_PHO_IRON_AGE','Samemroumos, also called Hypsouranios (''High of Heaven''), in Philo of Byblos (Eusebius, Praep. Ev. 1.10.9-10); among the mortal first generations, settler of Tyre and inventor of reed/rush dwellings, brother of Ousoos.'),
 ('ENT_PHO_KABEIROI','PER_PHO_IRON_AGE','In Philo of Byblos (Eusebius, Praep. Ev. 1.10.25) the seven sons of Sydyk plus Asclepius are the Kabeiroi, called Dioskouroi or Kabeiroi or Corybantes, who first invented the ship/raft; identified with the Great Gods of the Phoenician seafaring cult. A Phoenician interpretatio of the Greek Cabeiri (ENT_CABEIRI)/Dioscuri (ENT_DIOSCURI).');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_PHO_ELIOUN','member_of','ENT_PHO_PANTHEON','high','Elioun/Hypsistos is the primordial high god of the Phoenician theogony in Philo of Byblos.'),
 ('ENT_PHO_OURANOS','member_of','ENT_PHO_PANTHEON','high','Phoenician sky-god of the theogony.'),
 ('ENT_PHO_GE','member_of','ENT_PHO_PANTHEON','high','Phoenician earth-goddess of the theogony.'),
 ('ENT_PHO_ELOS_KRONOS','member_of','ENT_PHO_PANTHEON','high','Elos, the Phoenician El, is the chief god of Philo''s theogony.'),
 ('ENT_PHO_SYDYK','member_of','ENT_PHO_PANTHEON','high','Sydyk (Righteousness) is a primordial deity in Philo''s theogony.'),
 ('ENT_PHO_MISOR','member_of','ENT_PHO_PANTHEON','high','Misor (Uprightness) is a primordial deity in Philo''s theogony.'),
 ('ENT_PHO_CHOUSOR','member_of','ENT_PHO_PANTHEON','high','Chousor the craftsman-god belongs to the Phoenician pantheon per Philo.'),
 ('ENT_PHO_TAAUTOS','member_of','ENT_PHO_PANTHEON','high','Taautos the scribe-god is a deity of Philo''s Phoenician theogony.'),
 ('ENT_PHO_KABEIROI','member_of','ENT_PHO_PANTHEON','medium','The Kabeiroi/Dioskouroi, sons of Sydyk, are the Great Gods of the Phoenician seafaring cult in Philo.'),
 ('ENT_PHO_OURANOS','child_of','ENT_PHO_ELIOUN','high','Philo (Praep. Ev. 1.10.15-16): Ouranos and Ge are children of Elioun/Hypsistos.'),
 ('ENT_PHO_GE','child_of','ENT_PHO_ELIOUN','high','Philo (Praep. Ev. 1.10.15-16): Ge is daughter of Elioun/Hypsistos.'),
 ('ENT_PHO_OURANOS','consort_of','ENT_PHO_GE','high','Philo (Praep. Ev. 1.10.16): the sibling pair Ouranos and Ge marry and beget Elos/Kronos and his brothers.'),
 ('ENT_PHO_OURANOS','sibling_of','ENT_PHO_GE','high','Ouranos and Ge are both children of Elioun, brother and sister as well as consorts in Philo.'),
 ('ENT_PHO_ELOS_KRONOS','child_of','ENT_PHO_OURANOS','high','Philo (Praep. Ev. 1.10.16-21): Elos/Kronos is son of Ouranos and Ge and overthrows his father.'),
 ('ENT_PHO_ELOS_KRONOS','child_of','ENT_PHO_GE','high','Philo: Elos/Kronos is son of Ge by Ouranos.'),
 ('ENT_PHO_ELOS_KRONOS','opposes','ENT_PHO_OURANOS','high','Philo (Praep. Ev. 1.10.21): Elos/Kronos makes war on, castrates and dethrones his father Ouranos.'),
 ('ENT_PHO_KABEIROI','child_of','ENT_PHO_SYDYK','high','Philo (Praep. Ev. 1.10.25): the Kabeiroi/Dioskouroi are the sons of Sydyk.'),
 ('ENT_PHO_TAAUTOS','child_of','ENT_PHO_MISOR','high','Philo (Praep. Ev. 1.10.14): Taautos is the son of Misor.'),
 ('ENT_PHO_SYDYK','sibling_of','ENT_PHO_MISOR','medium','Philo pairs Sydyk and Misor as a kindred dyad of the same generation (Righteousness and Uprightness).'),
 ('ENT_PHO_ELOS_KRONOS','equated_with','ENT_CRONUS','high','Philo of Byblos explicitly identifies the Phoenician chief god Elos with the Greek Kronos (interpretatio graeca).'),
 ('ENT_PHO_ELOS_KRONOS','equated_with','ENT_CAN_EL','high','Elos is the Hellenized form of Northwest Semitic El; Philo''s Elos corresponds to the Ugaritic/Canaanite high god El.'),
 ('ENT_PHO_OURANOS','equated_with','ENT_OURANOS','high','Philo renders the Phoenician sky-god with the Greek name Ouranos, equating the two (interpretatio graeca).'),
 ('ENT_PHO_GE','equated_with','ENT_GAIA','high','Philo renders the Phoenician earth-goddess with the Greek name Ge (Gaia), equating the two (interpretatio graeca).'),
 ('ENT_PHO_CHOUSOR','equated_with','ENT_CAN_KOTHAR','high','Chousor is the Hellenized form of Ugaritic/Canaanite Kothar-wa-Khasis, the craftsman-god; same divine figure across the corpora.'),
 ('ENT_PHO_TAAUTOS','equated_with','ENT_EGY_THOTH','high','Philo (Praep. Ev. 1.9.24): Taautos is the one whom the Egyptians call Thouth (Thoth), the inventor of writing.'),
 ('ENT_PHO_KABEIROI','equated_with','ENT_CABEIRI','high','Philo names the sons of Sydyk Kabeiroi, the Phoenician interpretatio of the Greek Cabeiri (Great Gods of Samothrace).'),
 ('ENT_PHO_KABEIROI','equated_with','ENT_DIOSCURI','medium','Philo (Praep. Ev. 1.10.25) names the sons of Sydyk Dioskouroi as well as Kabeiroi/Corybantes.');
